CREATE TYPE payment_order_status AS ENUM ('CREATED', 'CAPTURED', 'FAILED', 'REFUND_INITIATED', 'REFUNDED', 'PARTIALLY_REFUNDED');
CREATE TYPE refund_status AS ENUM ('INITIATED', 'PROCESSING', 'COMPLETED', 'FAILED');
CREATE TABLE IF NOT EXISTS payment_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id text NOT NULL, user_id text NOT NULL, amount real NOT NULL, currency text NOT NULL DEFAULT 'INR', status payment_order_status NOT NULL DEFAULT 'CREATED', idempotency_key text NOT NULL UNIQUE, gateway_provider text NOT NULL DEFAULT 'razorpay', gateway_order_id text UNIQUE, gateway_payment_id text UNIQUE, gateway_signature text, failure_reason text, metadata jsonb, version integer NOT NULL DEFAULT 0, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS refunds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_order_id uuid NOT NULL REFERENCES payment_orders(id), amount real NOT NULL, reason text, status refund_status NOT NULL DEFAULT 'INITIATED', idempotency_key text NOT NULL UNIQUE, gateway_refund_id text UNIQUE, failure_reason text, metadata jsonb, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_order_id uuid NOT NULL REFERENCES payment_orders(id), action text NOT NULL, gateway_response jsonb, metadata jsonb, created_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS idempotency_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_key text NOT NULL UNIQUE, response jsonb, processed_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), topic text NOT NULL, key text, value jsonb NOT NULL, headers jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'PENDING', retry_count integer NOT NULL DEFAULT 0, max_retries integer NOT NULL DEFAULT 5, created_at timestamp NOT NULL DEFAULT now(), processed_at timestamp, last_error text);
